解题思路：
网上题解好像都是哈希和KMP的，但其实AC自动机也是可以做的(因为这是我AC自动机做题列表里的题...)

对于通配符 ∗ ，我们只需要把包含通配符的字符串以 ∗ 分开就好了，然后除了最后一段其他尽量匹配靠前的原串子串就好了，因为这样子匹配的话，如果中间夹杂其他字符是可以直接用 ∗ 代替的，这个思路也是哈希和 KMP 做法中的一种。

那么对于通配符 ? ，我们也仿照 ∗ ，根据 ? 分段，将分段之后的字符串丢到AC自动机里，然后用vector存下每段字符串在原串中的位置，其实也就是用vector存end数组，因为分段的串可能会重复。

举个例子，对于串abcd?abc?cd?abcd，建出来的Trie树如下：



其中绿色(我也不知道是啥颜色)的节点是结束节点，旁边标注的数字则是以它结尾的字符串们在原串中的位置，建fail指针和正常的AC自动机建法是一样的。

我们用一个cnt数组，下标对应原串中的每一位，然后在AC自动机上跑，如果匹配到结束节点，那么就让cnt[pos−ed[p][j]+1]++，其中pos为当前匹配位置，ed[p]则是上述的vector数组。

这样处理之后，我们再遍历一遍，如果有一个cnt值等于段数，那么它就可以作为这整个串的匹配的起点。

就如之前的串abcd?abc?cd?abcd，每一个这样子处理之后，只有第一个abcd的a节点是满足cnt等于段数，那么它就是这次能够匹配的最靠前的位置了。

Code：
/*Program from Luvwgyx*/
#include<queue>
#include<vector>
#include<cstdio>
#include<cstring>
#include<algorithm>
using namespace std;
const int maxn=1e5+10;
int n,m,num;bool Beg,End;char s[maxn],t[maxn];
int read(){
    int x=0,f=1;char ch=getchar();
    while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}
void print(int x){
    if(x<0)putchar('-'),x=-x;
    if(x>9)print(x/10);
    putchar(x%10+'0');
}
void write(int x){print(x);puts("");}
struct AC_automaton{
    vector<int >ed[maxn];queue<int >q;
    int tot,root,cnt[maxn],seq[maxn],fail[maxn],trie[maxn][26];
    int newnode(){
        tot++;fail[tot]=0;ed[tot].clear();
        for(int i=0;i<26;i++)trie[tot][i]=-1;
        return tot;
    }
    void insert(int l,int r,int id){
        int p=root;
        for(int i=l;i<=r;i++){
            int ch=t[i]-'a';
            if(trie[p][ch]==-1)trie[p][ch]=newnode();
            p=trie[p][ch];
        }ed[p].push_back(id);
    }
    void make_fail(){
        for(int i=0;i<26;i++)
            if(trie[root][i]!=-1){
                fail[trie[root][i]]=root;
                q.push(trie[root][i]);
            }else trie[root][i]=root;
        while(!q.empty()){
            int x=q.front();q.pop();
            for(int i=0;i<(int)ed[fail[x]].size();i++)ed[x].push_back(ed[fail[x]][i]);
            for(int i=0;i<26;i++){
                if(trie[x][i]!=-1){
                    fail[trie[x][i]]=trie[fail[x]][i];
                    q.push(trie[x][i]);
                }else trie[x][i]=trie[fail[x]][i];
            }
        }
    }
    bool find(int l,int r,bool fir,bool las){
        tot=0;root=newnode();
        memset(cnt,0,sizeof(cnt));
        int bel=0;
        for(int i=l,pos=i;i<=r;i++,pos=i)
            if(t[i]!='?'){
                while(pos<=r&&t[pos]!='?')pos++;
                pos--;insert(i,pos,pos-l+1);
                i=pos;bel++;
            }
        make_fail();int p=root;
        for(int i=1;i<=n;i++){
            int ch=s[i]-'a';p=trie[p][ch];
            for(int j=0;j<(int)ed[p].size();j++)
                if(i-ed[p][j]+1>0)cnt[i-ed[p][j]+1]++;
        }
        for(int i=1;i<=n;i++)
            if(cnt[i]==bel){
                if(!num){
                    if(!Beg&&fir&&i!=1)continue;
                    if(!End&&las&&i+r-l!=n)continue;
                    seq[++num]=i+r-l;
                    return 1;
                }else {
                    if(i<=seq[num])continue;
                    if(!End&&las&&i+r-l!=n)continue;
                    seq[++num]=i+r-l;
                    return 1;
                }
            }
        return 0;
    }
}AC;
int main(){
    scanf("%s",t+1);int T=read();m=strlen(t+1);
    while(T--){
        scanf("%s",s+1);n=strlen(s+1);num=0;
        Beg=t[1]=='*';End=t[m]=='*';int len=m;
        while(len&&t[len]=='*')len--;
        if(!len){puts("YES");continue;}
        int bel=0;bool flag=0;
        for(int i=1;i<=m;i++)
            if(t[i]!='*'){
                int pos=i;
                while(pos<=m&&t[pos]!='*')pos++;pos--;
                if(!AC.find(i,pos,bel==0,pos==len)){flag=1;break;}
                i=pos;bel++;
            }
        puts(flag?"NO":"YES");
    }
    return 0;
}

